syntax:
typedef <type> <new_type_name>;
// For example:
typedef int complex;

// Using elaborated-type-specifier in declarations:
struct S { int a; };
struct S s;
// or
struct S *ptr;

// Combining typedefs with elaborated-type-specifiers:
typedef struct S myStruct;
myStruct instance;

// Note: Redefining a typedef with a class or struct name can cause errors:
typedef int complex;
class complex { /* ... */ }; // error: redefinition
